public class PasswordGenerator {

    private static final String LETTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String DIGITS = "0123456789";
    private static final String SYMBOLS = "!@#$%^&*()-_=+";
    private static final String ALL = LETTERS + DIGITS + SYMBOLS;

    private static final SecureRandom RANDOM = new SecureRandom();

    /**
     * Generates a random password of the given length.
     * The last character is restricted to a letter or digit (no symbol),
     * to avoid trailing characters that some systems trim or mishandle.
     *
     * @param length the desired password length (must be >= 1)
     * @return the generated password
     */
    public static String generatePassword(int length) {
        if (length < 1) {
            throw new IllegalArgumentException("Password length must be at least 1");
        }

        StringBuilder password = new StringBuilder(length);

        // All characters except the last are drawn from the full set.
        for (int i = 0; i < length - 1; i++) {
            password.append(ALL.charAt(RANDOM.nextInt(ALL.length())));
        }

        // The final character is restricted to letters and digits only.
        String endSet = LETTERS + DIGITS;
        password.append(endSet.charAt(RANDOM.nextInt(endSet.length())));

        return password.toString();
    }
}

