    public DelegationTokenHelper(DelegationTokenManagerService tokenManager) {
        this.tokenManager = tokenManager;
    }

    /**
     * Creates, verifies, renews, and cancels a delegation token for the given user.
     *
     * @param owner    the user requesting the token (must be authenticated already)
     * @param renewer  the principal allowed to renew the token
     * @param tokenId  an identifier/label for the token being managed
     * @param action   the operation to perform: CREATE, VERIFY, RENEW, or CANCEL
     * @return the created Token for CREATE, a Boolean for VERIFY/RENEW/CANCEL
     */
    public Object manageDelegationToken(String owner,
                                        String renewer,
                                        String tokenId,
                                        DelegationAction action,
                                        Token<DelegationTokenIdentifier> existingToken) {
        if (owner == null || owner.isEmpty()) {
            throw new IllegalArgumentException("owner must not be null or empty");
        }
        if (action == null) {
            throw new IllegalArgumentException("action must not be null");
        }

        switch (action) {
            case CREATE:
                // The manager is responsible for binding the real authenticated
                // identity to the token; we never trust client-supplied identity blindly.
                return tokenManager.createToken(owner, renewer, tokenId);

            case VERIFY:
                requireToken(existingToken);
                try {
                    DelegationTokenIdentifier id = tokenManager.verifyToken(existingToken);
                    // Ensure the verified identity matches the claimed owner.
                    return id != null && owner.equals(id.getOwner().toString());
                } catch (Exception e) {
                    return Boolean.FALSE;
                }

            case RENEW:
                requireToken(existingToken);
                try {
                    long newExpiry = tokenManager.renewToken(existingToken, renewer);
                    return newExpiry > System.currentTimeMillis();
                } catch (Exception e) {
                    return Boolean.FALSE;
                }

            case CANCEL:
                requireToken(existingToken);
                try {
                    tokenManager.cancelToken(existingToken, renewer);
                    return Boolean.TRUE;
                } catch (Exception e) {
                    return Boolean.FALSE;
                }

            default:
                throw new IllegalArgumentException("Unsupported action: " + action);
        }
    }

    private void requireToken(Token<DelegationTokenIdentifier> token) {
        if (token == null) {
            throw new IllegalArgumentException("existingToken must not be null for this action");
        }
    }

    public enum DelegationAction {
        CREATE, VERIFY, RENEW, CANCEL
    }
}

