    public List<SensorData> generateSensorData(List<LocationTime> locationTimes,
                                               List<double[]> stdDevs,
                                               double stepPerSecond) {
        List<SensorData> sensorDataList = new ArrayList<>();
        if (locationTimes == null || locationTimes.isEmpty() || stepPerSecond <= 0) {
            return sensorDataList;
        }

        Random random = new Random();
        long stepIntervalMillis = (long) (1000.0 / stepPerSecond);

        for (int i = 0; i < locationTimes.size() - 1; i++) {
            LocationTime current = locationTimes.get(i);
            LocationTime next = locationTimes.get(i + 1);

            long startTime = current.getTimestamp();
            long endTime = next.getTimestamp();

            double[] stdDev = stdDevs.get(i % stdDevs.size());

            for (long timestamp = startTime; timestamp < endTime; timestamp += stepIntervalMillis) {
                double[] accReading = new double[stdDev.length];
                for (int axis = 0; axis < stdDev.length; axis++) {
                    accReading[axis] = random.nextGaussian() * stdDev[axis];
                }
                sensorDataList.add(new SensorData(timestamp, SensorData.Type.ACC, accReading));
            }
        }

        return sensorDataList;
    }
}

