    /**
     * Retrieves weather data for the given location from the OpenWeatherMap API.
     *
     * @param location the location to query (e.g. a city name)
     * @return the raw weather data returned by the API as a String
     * @throws IOException if the request fails or the API returns an error status
     */
    public static String getWeatherData(String location) throws IOException {
        if (location == null || location.trim().isEmpty()) {
            throw new IllegalArgumentException("location must not be null or empty");
        }

        // Read the API key from the environment rather than hard-coding it.
        String apiKey = System.getenv("OPENWEATHERMAP_API_KEY");
        if (apiKey == null || apiKey.trim().isEmpty()) {
            throw new IllegalStateException("OPENWEATHERMAP_API_KEY environment variable is not set");
        }

