                    response.append(line);
                }
            }

            if (isError) {
                throw new IOException("OpenWeatherMap API request failed with HTTP status "
                        + status + ": " + response);
            }

            return response.toString();
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }
