    private final String address;
    private final int port;
    private final Selector selector;
    private final ServerSocketChannel serverChannel;
    private volatile boolean running = true;

    public NioServer(String address, int port) throws IOException {
        this.address = address;
        this.port = port;
        this.selector = Selector.open();
        this.serverChannel = ServerSocketChannel.open();
        this.serverChannel.bind(new InetSocketAddress(address, port));
        this.serverChannel.configureBlocking(false);
        this.serverChannel.register(selector, SelectionKey.OP_ACCEPT);
    }

    public void start() {
        System.out.println("Server listening on " + address + ":" + port);
        startConsole();
        runEventLoop();
    }

    private void runEventLoop() {
        try {
            while (running) {
                if (selector.select(500) == 0) {
                    continue;
                }
                Set<SelectionKey> keys = selector.selectedKeys();
                Iterator<SelectionKey> it = keys.iterator();
                while (it.hasNext()) {
                    SelectionKey key = it.next();
                    it.remove();
                    if (!key.isValid()) {
                        continue;
                    }
                    if (key.isAcceptable()) {
                        accept(key);
                    } else if (key.isReadable()) {
                        read(key);
                    }
                }
            }
        } catch (IOException e) {
            System.err.println("Event loop error: " + e.getMessage());
        } finally {
            shutdown();
        }
    }

    private void accept(SelectionKey key) throws IOException {
        ServerSocketChannel server = (ServerSocketChannel) key.channel();
        SocketChannel client = server.accept();
        if (client != null) {
            client.configureBlocking(false);
            client.register(selector, SelectionKey.OP_READ);
            System.out.println("Accepted connection from " + client.getRemoteAddress());
        }
    }

    private void read(SelectionKey key) {
        SocketChannel client = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        try {
            int bytesRead = client.read(buffer);
            if (bytesRead == -1) {
                System.out.println("Connection closed: " + client.getRemoteAddress());
                key.cancel();
                client.close();
                return;
            }
            buffer.flip();
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            String message = new String(data, StandardCharsets.UTF_8).trim();
            System.out.println("Received: " + message);
            client.write(ByteBuffer.wrap(("Echo: " + message + "\n").getBytes(StandardCharsets.UTF_8)));
        } catch (IOException e) {
            key.cancel();
            try {
                client.close();
            } catch (IOException ignored) {
            }
        }
    }

    private void startConsole() {
        Thread consoleThread = new Thread(() -> {
            Scanner scanner = new Scanner(System.in);
            System.out.println("Console ready. Commands: help, stop");
            while (running && scanner.hasNextLine()) {
                String command = scanner.nextLine().trim();
                handleCommand(command);
            }
            scanner.close();
        });
        consoleThread.setDaemon(true);
        consoleThread.start();
    }

    private void handleCommand(String command) {
        switch (command.toLowerCase()) {
            case "stop":
            case "exit":
                System.out.println("Shutting down server...");
                running = false;
                selector.wakeup();
                break;
            case "help":
                System.out.println("Available commands: help, stop, exit");
                break;
            case "":
                break;
            default:
                System.out.println("Unknown command: " + command);
        }
    }

    private void shutdown() {
        try {
            serverChannel.close();
            selector.close();
            System.out.println("Server stopped.");
        } catch (IOException e) {
            System.err.println("Shutdown error: " + e.getMessage());
        }
    }

    public static void main(String[] args) throws IOException {
        String address = args.length > 0 ? args[0] : "127.0.0.1";
        int port = args.length > 1 ? Integer.parseInt(args[1]) : 8080;
        new NioServer(address, port).start();
    }
}
