public class UrlResolver {

    /**
     * Validates and resolves a list of URL strings into InetSocketAddress objects.
     *
     * Invalid URLs, entries missing host or port information, and hosts that fail
     * DNS resolution are skipped rather than aborting the whole operation.
     *
     * @param urls the candidate URL strings (may be null or contain null entries)
     * @return a list of successfully resolved, unresolved-free InetSocketAddress objects
     */
    public static List<InetSocketAddress> resolveAddresses(List<String> urls) {
        List<InetSocketAddress> resolved = new ArrayList<>();
        if (urls == null) {
            return resolved;
        }

        for (String raw : urls) {
            if (raw == null || raw.trim().isEmpty()) {
                continue;
            }

            final URI uri;
            try {
                uri = new URI(raw.trim());
            } catch (URISyntaxException e) {
                // Malformed URL: skip.
                continue;
            }

            String host = uri.getHost();
            if (host == null || host.isEmpty()) {
                // Missing host information: skip.
                continue;
            }

            int port = uri.getPort();
            if (port == -1) {
                // No explicit port; fall back to a scheme default when known.
                port = defaultPortForScheme(uri.getScheme());
                if (port == -1) {
                    // Missing port information and no sensible default: skip.
                    continue;
                }
            }

            if (port < 0 || port > 65535) {
                // Port out of valid range: skip.
                continue;
            }

            try {
                // Force DNS resolution so failures are caught here rather than later.
                InetAddress address = InetAddress.getByName(host);
                InetSocketAddress socketAddress = new InetSocketAddress(address, port);
                if (!socketAddress.isUnresolved()) {
                    resolved.add(socketAddress);
                }
            } catch (UnknownHostException e) {
                // DNS resolution failure: skip.
                continue;
            } catch (IllegalArgumentException e) {
                // Invalid port/address combination: skip.
                continue;
            }
        }

        return resolved;
    }

    private static int defaultPortForScheme(String scheme) {
        if (scheme == null) {
            return -1;
        }
        switch (scheme.toLowerCase()) {
            case "http":
            case "ws":
                return 80;
            case "https":
            case "wss":
                return 443;
            case "ftp":
                return 21;
            default:
                return -1;
        }
    }
}

