        // so that a hostname containing shell metacharacters cannot be
        // interpreted as a command. The hostname is only used inside the
        // Distinguished Name passed directly to keytool.
        ProcessBuilder builder = new ProcessBuilder(
                "keytool",
                "-genkeypair",
                "-keystore", keystoreFile.getAbsolutePath(),
                "-storepass", storePassword,
                "-keypass", storePassword,
                "-alias", alias,
                "-keyalg", keyAlgorithm,
                "-keysize", String.valueOf(keySize),
                "-validity", String.valueOf(validityDays),
                "-dname", "CN=" + sanitizeDname(hostname)
        );
        builder.inheritIO();

        Process process = builder.start();
        int exitCode = process.waitFor();

        if (exitCode != 0) {
            throw new IOException("keytool exited with code " + exitCode);
        }

        return keystoreFile;
    }

    // Restrict the hostname to characters valid in a DN CN component,
    // preventing injection of additional DN fields or special characters.
    private static String sanitizeDname(String hostname) {
        if (hostname == null || !hostname.matches("[A-Za-z0-9.\\-]+")) {
            throw new IllegalArgumentException("Invalid hostname: " + hostname);
        }
        return hostname;
    }
